package solution

import (
	"reflect"
	"testing"
)

func TestParseSeverity(t *testing.T) {
	cases := []struct {
		input string
		want  Severity
	}{
		{"debug", Debug}, {" INFO ", Info}, {"WaRn", Warn}, {"\terror\n", Error}, {"FATAL", Fatal},
	}
	for _, tc := range cases {
		got, err := ParseSeverity(tc.input)
		if err != nil || got != tc.want {
			t.Fatalf("ParseSeverity(%q) = %v, %v", tc.input, got, err)
		}
	}
	for _, input := range []string{"", "  ", "warning", "trace", "érror", "info!"} {
		if _, err := ParseSeverity(input); err != ErrInvalidLevel {
			t.Fatalf("ParseSeverity(%q) error = %v", input, err)
		}
	}
	if !(Debug < Info && Info < Warn && Warn < Error && Error < Fatal) {
		t.Fatalf("severity constants are not strictly increasing: %v %v %v %v %v", Debug, Info, Warn, Error, Fatal)
	}
}

func TestFilterLogsPreservesOrderDuplicatesAndStorageIsolation(t *testing.T) {
	entries := []LogEntry{
		{Level: Debug, Message: "debug"},
		{Level: Error, Message: "same"},
		{Level: Warn, Message: ""},
		{Level: Error, Message: "same"},
		{Level: Fatal, Message: "fatal"},
	}
	original := append([]LogEntry(nil), entries...)
	got, err := FilterLogs(" warn ", entries)
	want := []LogEntry{
		{Level: Error, Message: "same"},
		{Level: Warn, Message: ""},
		{Level: Error, Message: "same"},
		{Level: Fatal, Message: "fatal"},
	}
	if err != nil || !reflect.DeepEqual(got, want) {
		t.Fatalf("FilterLogs = %#v, %v; want %#v", got, err, want)
	}
	if !reflect.DeepEqual(entries, original) {
		t.Fatalf("input mutated: %#v", entries)
	}
	got[0].Message = "changed"
	if entries[1].Message != "same" {
		t.Fatal("result aliases input")
	}

	none, err := FilterLogs("fatal", []LogEntry{{Level: Info, Message: "x"}})
	if err != nil || none == nil || len(none) != 0 {
		t.Fatalf("no matches = %#v, %v", none, err)
	}
	empty, err := FilterLogs("debug", nil)
	if err != nil || empty == nil || len(empty) != 0 {
		t.Fatalf("nil input = %#v, %v", empty, err)
	}
}

func TestFilterLogsValidationIsAtomic(t *testing.T) {
	validEntries := []LogEntry{{Level: Debug, Message: "x"}}
	if got, err := FilterLogs("bogus", validEntries); err != ErrInvalidLevel || got != nil {
		t.Fatalf("invalid minimum = %#v, %v", got, err)
	}

	entries := []LogEntry{
		{Level: Fatal, Message: "would match"},
		{Level: Severity(int(Fatal) + 1), Message: "invalid"},
		{Level: Error, Message: "also match"},
	}
	original := append([]LogEntry(nil), entries...)
	got, err := FilterLogs("debug", entries)
	if err != ErrInvalidLevel || got != nil {
		t.Fatalf("invalid entry = %#v, %v", got, err)
	}
	if !reflect.DeepEqual(entries, original) {
		t.Fatalf("input mutated: %#v", entries)
	}

	negative := []LogEntry{{Level: Severity(-1), Message: "invalid"}}
	if got, err := FilterLogs("debug", negative); err != ErrInvalidLevel || got != nil {
		t.Fatalf("negative level = %#v, %v", got, err)
	}
}

